import{z as i,x as s,o as e,c as l,q as B,j as A,D as a,d as r,s as o,S as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"合同与机制收束","description":"","frontmatter":{"title":"合同与机制收束","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ct-map.md","filePath":"econ/ct-map.md","lastUpdated":1791063341000}'),c={name:"econ/ct-map.md"};function d(h,E,m,p,C,D){const t=s("Mermaid");return e(),l("div",null,[E[2]||(E[2]=B('<h1 id="合同与机制收束" tabindex="-1">合同与机制收束 <a class="header-anchor" href="#合同与机制收束" aria-label="Permalink to &quot;合同与机制收束&quot;">​</a></h1><div class="epigraph"><p>机制设计的全部产出是一张约束表：谁在什么时候知道什么、能对什么承诺；剩下的是求解。</p><footer>—— 据 Holmström, Bell Journal of Economics, 1979；Myerson, Mathematics of Operations Research, 1981；Maskin, Review of Economic Studies, 1999 整理</footer></div><p><a href="/econ/ct-matching-deep">上一课</a>把清台所与稳定市场写完，本课程到此收束。回看路线：合同单元从<a href="/econ/ct-moral-hazard-deep">道德风险的深化</a>走到<a href="/econ/ct-adverse-selection-deep">逆向选择的深化</a>再到<a href="/econ/ct-dynamic-contracts">动态合同</a>，在双边关系里把激励的几何写尽；机制单元从<a href="/econ/ct-multilateral-mechanism">多边机制设计</a>经<a href="/econ/ct-auction-theory-deep">拍卖理论的深化</a>到<a href="/econ/ct-matching-deep">匹配市场的深化</a>，把人数与规则本身变成设计对象。收束课不引入新模型，只把六个模型折回一张地图，标出边界与端口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>六个模型有一个共同的骨架：一方知道或能做的比别人多，而承诺要靠条款实现。骨架长出三个摩擦——隐藏行动、隐藏类型、无法承诺；机制设计把它们写成同一组约束：IC 保证说真话或真努力可自我执行，IR 保证参与，再加预算、货币、偏好域这些场地条件。收束的问题因此是会计问题：三种摩擦的解各自付出什么成本、这些成本在哪些课里换过名字、哪些定理宣布某些组合根本买不到。不收这张账，每课的技巧是孤立的；收了它，新问题来了才知道该开哪个抽屉。</p><p><span class="marginnote">术语翻译：IC（激励相容）就是「让对方算完账后自愿说真话/干真活」的手段来做「不需要监督」的事；IR（参与约束）就是「保底不亏」来做「对方愿意进门」的事。每个机制都先过这两关：IR 决定人来不来，IC 决定来了后演不演。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读图有一套固定顺序：先写约束表——谁先动、谁知道什么、能承诺什么；再查禁航区——不可能定理群；最后挑均衡概念。禁航区是地图上的既定地形，不是脚注：<a href="/econ/gibbard-satterthwaite">Gibbard–Satterthwaite</a> 划掉无货币的占优策略实施，<a href="/econ/myerson-satterthwaite">Myerson–Satterthwaite</a> 划掉双边交易的效率加预算平衡，<a href="/econ/rs-unraveling">RS 崩溃</a>划掉竞争筛选的存在性保证，<a href="/econ/matching-strategy-proof">策略证明</a>划掉匹配的双边诚实。每条定理标出「哪里必须放弃什么」，于是设计成为在禁航区之间选航道——退均衡概念、加货币、限偏好域、放大市场，四个动作解释了本课程出现的每一个机制。</p>',8)),(e(),A(n,null,{default:a(()=>[o(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FR%5B%22%E4%B8%89%E7%A7%8D%E6%91%A9%E6%93%A6%EF%BC%9A%E9%9A%90%E8%97%8F%E8%A1%8C%E5%8A%A8%20%2F%20%E9%9A%90%E8%97%8F%E7%B1%BB%E5%9E%8B%20%2F%20%E4%B8%8D%E5%8F%AF%E6%89%BF%E8%AF%BA%22%5D%20--%3E%20RP%5B%22%E6%98%BE%E7%A4%BA%E5%8E%9F%E7%90%86%EF%BC%9A%E5%8F%AA%E5%9C%A8%20IC%20%E7%9B%B4%E6%8E%A5%E6%9C%BA%E5%88%B6%E4%B8%8A%E6%90%9C%E7%B4%A2%22%5D%0A%20%20RP%20--%3E%20ENV%5B%22%E5%8C%85%E7%BB%9C%EF%BC%9A%E6%94%AF%E4%BB%98%E8%A2%AB%E9%85%8D%E7%BD%AE%E9%92%89%E6%AD%BB%EF%BC%8C%E7%A7%9F%E9%87%91%E5%8F%AA%E5%89%A9%E5%B8%B8%E6%95%B0%22%5D%0A%20%20ENV%20--%3E%20BAL%5B%22%E7%A7%9F%E9%87%91%E2%80%93%E6%95%88%E7%8E%87%E6%9D%83%E8%A1%A1%E5%AE%9A%E6%89%AD%E6%9B%B2%22%5D%0A%20%20BAL%20--%3E%20A%5B%22%E5%8F%8C%E8%BE%B9%E5%90%88%E5%90%8C%EF%BC%9A%E9%81%93%E5%BE%B7%E9%A3%8E%E9%99%A9%E4%B8%8E%E7%AD%9B%E9%80%89%22%5D%0A%20%20BAL%20--%3E%20B%5B%22%E5%A4%9A%E8%BE%B9%E6%9C%BA%E5%88%B6%EF%BC%9A%E5%AE%9E%E6%96%BD%E3%80%81%E9%A2%84%E7%AE%97%E3%80%81%E5%90%88%E8%B0%8B%22%5D%0A%20%20BAL%20--%3E%20C%5B%22%E5%B8%82%E5%9C%BA%E8%AE%BE%E8%AE%A1%EF%BC%9A%E6%8B%8D%E5%8D%96%E4%B8%8E%E5%8C%B9%E9%85%8D%22%5D%0A%20%20NO%5B%22%E4%B8%8D%E5%8F%AF%E8%83%BD%E5%AE%9A%E7%90%86%E7%BE%A4%EF%BC%9AG%E2%80%93S%20%2F%20M%E2%80%93S%20%2F%20RS%20%2F%20%E5%8F%8C%E8%BE%B9%E6%BF%80%E5%8A%B1%22%5D%20-.-%3E%7C%22%E5%88%92%E6%8E%89%E4%B9%B0%E4%B8%8D%E5%88%B0%E7%9A%84%E7%BB%84%E5%90%88%22%7C%20BAL%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="一笔租金的四种形态" tabindex="-1">一笔租金的四种形态 <a class="header-anchor" href="#一笔租金的四种形态" aria-label="Permalink to &quot;一笔租金的四种形态&quot;">​</a></h3><p>贯穿全部课程的是信息租金的会计。筛选里，租金付给高效率者求他说真话，成本写成低类型的产量扭曲；道德风险里，租金付给风险厌恶者的风险承担，成本写成保险与激励的权衡；拍卖里，租金被虚拟价值压到临界，成本写成保留价下的不成交；匹配里，租金换成配对剩余的分配端点，成本写成单边策略证明的缺口。四处同名不同形，但包络方法把它们压成同一步运算——支付由配置钉死，搜索空间塌掉，这是本课程最重要的技术遗产。</p><p><span class="marginnote">验证一遍就会看见骨架的普适：最优税的顶端零税率、最优拍卖的虚拟保留价、筛选的顶端无扭曲，是同一条虚拟边际式 \\(J(\\theta)=\\theta-\\frac{1-F}{f}\\) 在福利、拍卖、产品线三个市场里的三次显影。</span></p><p><span class="marginnote">数字实例：设报价 \\(\\theta=10\\)，类型分布均匀于 \\([0,10]\\)，则 \\(F(\\theta)=1\\)、\\(f=0.1\\)，虚拟价值 \\(J=10-\\frac{1-1}{0.1}=10\\)，报价多少都愿意成交；若 \\(\\theta=1\\)，则 \\(J=1-\\frac{0.9}{0.1}=-8\\)，低于零，卖方宁可不卖。保留价、顶端零扭曲都从这一个减法里长出来。</span></p>',5)),(e(),A(n,null,{default:a(()=>[o(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20R%5B%22%E4%BF%A1%E6%81%AF%E7%A7%9F%E9%87%91%EF%BC%9A%E7%9C%9F%E8%AF%9D%E4%B8%8E%E7%9C%9F%E5%8A%AA%E5%8A%9B%E7%9A%84%E5%AF%B9%E4%BB%B7%22%5D%20--%3E%20S%5B%22%E7%AD%9B%E9%80%89%EF%BC%9A%E4%BB%98%E7%BB%99%E9%AB%98%E6%95%88%E7%8E%87%E8%80%85%22%5D%0A%20%20S%20--%3E%20CS%5B%22%E6%88%90%E6%9C%AC%20%3D%20%E4%BD%8E%E7%B1%BB%E5%9E%8B%E4%BA%A7%E9%87%8F%E6%89%AD%E6%9B%B2%22%5D%0A%20%20R%20--%3E%20M%5B%22%E9%81%93%E5%BE%B7%E9%A3%8E%E9%99%A9%EF%BC%9A%E4%BB%98%E7%BB%99%E9%A3%8E%E9%99%A9%E5%8E%8C%E6%81%B6%E8%80%85%22%5D%0A%20%20M%20--%3E%20CM%5B%22%E6%88%90%E6%9C%AC%20%3D%20%E4%BF%9D%E9%99%A9%E4%B8%8E%E6%BF%80%E5%8A%B1%E7%9A%84%E6%9D%83%E8%A1%A1%22%5D%0A%20%20R%20--%3E%20AU%5B%22%E6%8B%8D%E5%8D%96%EF%BC%9A%E8%A2%AB%E8%99%9A%E6%8B%9F%E4%BB%B7%E5%80%BC%E5%8E%8B%E5%88%B0%E4%B8%B4%E7%95%8C%22%5D%0A%20%20AU%20--%3E%20CA%5B%22%E6%88%90%E6%9C%AC%20%3D%20%E4%BF%9D%E7%95%99%E4%BB%B7%E4%B8%8B%E4%B8%8D%E6%88%90%E4%BA%A4%22%5D%0A%20%20R%20--%3E%20MA%5B%22%E5%8C%B9%E9%85%8D%EF%BC%9A%E5%89%A9%E4%BD%99%E5%88%86%E9%85%8D%E7%9A%84%E7%AB%AF%E7%82%B9%22%5D%0A%20%20MA%20--%3E%20CM2%5B%22%E6%88%90%E6%9C%AC%20%3D%20%E5%8D%95%E8%BE%B9%E7%AD%96%E7%95%A5%E8%AF%81%E6%98%8E%E7%9A%84%E7%BC%BA%E5%8F%A3%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p>对外有两个端口。实证端口：结构估计把 IC 均衡变成反事实机器，<a href="/econ/auction-structural-estimation">拍卖的结构估计</a>到<a href="/econ/se-auction-deep">深化</a>是样例——先检查均衡前提，再让模型回答反事实。应用端口：<a href="/econ/mirrlees-optimal-tax">最优所得税</a>、<a href="/econ/efficiency-wage">效率工资</a>、<a href="/econ/deposit-insurance">存款保险</a>分别是筛选、道德风险、动态合同在各市场的常驻形态；它们不是「例子」，是同一台机器换数据运转。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>地图本身有三块未绘区域。稳健性：多数结论依赖共同先验与偏好精确已知，对信息结构稳健的机制设计与对行为违例的容忍是活跃前沿。行为：现实人不像 IC 假设那样最优化，<a href="/econ/commitment-devices">承诺装置</a>一类证据提示激励设计要为误差留边，本课程按理性人收束。计算：包络与格结构删搜索，但多维类型与组合拍卖的可实施集仍然算不动，理论可行与工程可算之间隔着数值。这三块共同说明：本课程交付的是约束表与求解语法，不是一份能直接施工的图纸。</p><p><span class="marginnote">术语翻译：共同先验就是「所有人共享同一份对世界概率的手册」——大家看法不同只因为拿到的信息不同，而不是因为算概率的思路不同。它让「我知道你知道我知道」能一层层算下去；一旦现实里大家用不同的手册，机制的均衡就可能在地图上标不到的位置。</span></p><p>后课默认：遇到任何「谁先动、谁知道什么、能承诺什么」的问题，先写约束表、查禁航区、再挑均衡概念——顺序不能反。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三摩擦一骨架：隐藏行动、隐藏类型、不可承诺，统一写成 IC 与 IR 上的优化。</li><li>信息租金是贯穿会计：扭曲、风险溢价、保留价、分配端点是它的四种形态。</li><li>包络与格结构是本课程的核心技术：支付被钉死，搜索空间塌掉。</li><li>不可能定理群是禁航区，四个补救动作解释全部机制的选择。</li><li>对外端口是结构估计与各市场应用；未绘区域是稳健、行为与计算。</li><li>出处：Holmström, <em>Bell</em> 1979；Myerson, <em>Math. Oper. Res.</em> 1981；Maskin, <em>REStud</em> 1999；Hatfield and Milgrom, <em>REStud</em> 2005 及本课程各课所引原始文献。</li></ul>',7))])}const _=i(c,[["render",d]]);export{f as __pageData,_ as default};
